# ==============================================================================# IOTEC MISSION CONTROL# 004_DATABASE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)cur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS missions(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    title TEXT,    status TEXT,    priority TEXT,    responsible TEXT)""")cur.execute("""CREATE TABLE IF NOT EXISTS events(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    event TEXT,    origin TEXT,    payload TEXT)""")cur.execute("""CREATE TABLE IF NOT EXISTS logs(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    level TEXT,    message TEXT)""")conn.commit()cur.execute("SELECT COUNT(*) FROM missions")missions = cur.fetchone()[0]cur.execute("SELECT COUNT(*) FROM events")events = cur.fetchone()[0]cur.execute("SELECT COUNT(*) FROM logs")logs = cur.fetchone()[0]print("=" * 80)print("DATABASE ONLINE")print("=" * 80)print(f"Banco......: {DB}")print(f"Missions...: {missions}")print(f"Events.....: {events}")print(f"Logs.......: {logs}")conn.close()print("=" * 80)print("DATABASE READY")print("=" * 80)

